  "Burger King": "#D52001",
  "Captain D's": "#02A6E4",
  "Club Pilates": "#5F8DC9",
  "Club Pilates Franchise": "#5F8DC9",
  "Crunch": "#F58038",
  "Crunch Fitness": "#F58038",
  "Dave's Hot Chicken": "#F6E719",
  "Denny's": "#CB272C",
  "Dunkin'": "#F36901",
  "European Wax Center": "#F02134",
  "F45 Training": "#E21D2F",
  "Firehouse Subs": "#C20302",
  "Five Guys": "#D21134",
  "Gold's Gym": "#FFD402",
  "IHOP": "#0A77BE",
  "Jersey Mike's": "#0A4477",
  "Jimmy John's": "#E30133",
  "Massage Envy": "#A19BC8",
  "McDonald's": "#DB0108",
