const FRANCHISE_ACCENT_COLOR_FALLBACK = "#7A63DD";

function getFranchiseAccentColor(franchiseName) {
  return FRANCHISE_ACCENT_COLORS[franchiseName] || FRANCHISE_ACCENT_COLOR_FALLBACK;
}

const WEFRANCH_FRANCHISE_BASE = "https://wefranch.com/franchise";

// Known wefranch brand pages. CST dump concepts are registered at runtime
// from publicId + slug; these cover seeded / candidate brands the dump omits.
const FRANCHISE_WEFRANCH_PROFILES = {
  "Anytime Fitness": { publicId: "e4xk", slug: "anytime-fitness" },
  "Crumbl Cookies": { publicId: "d853", slug: "crumbl" },
  "Drybar": { publicId: "dn3k", slug: "drybar" },
  "F45 Training": { publicId: "dq3j", slug: "f45-training" },
  "Gold's Gym": { publicId: "dnql", slug: "golds-gym" },
  "MaidPro": { publicId: "ejmy", slug: "maidpro" },
  "Mathnasium": { publicId: "gl46", slug: "mathnasium" },
  "Snap Fitness": { publicId: "179m", slug: "snap-fitness" },
  "StretchLab": { publicId: "xrjz", slug: "stretchlab" },
  "The Learning Experience": { publicId: "nkxj", slug: "the-learning-experience" },
  "Wendy's": { publicId: "dzwp", slug: "wendys" }
};

const FRANCHISE_WEFRANCH_ALIASES = {
  "Club Pilates": "Club Pilates Franchise",
  "Crunch Fitness": "Crunch",
  "OrangeTheory Fitness": "Orangetheory",
  "Orangetheory Fitness": "Orangetheory",
  "Popeyes": "Popeyes Louisiana Kitchen"
};

function registerFranchiseWefranchProfile(name, publicId, slug) {
  const brandName = String(name || "").trim();
  const id = String(publicId || "").trim();
  const brandSlug = String(slug || "").trim();
  if (!brandName || !id || !brandSlug) return;
  FRANCHISE_WEFRANCH_PROFILES[brandName] = { publicId: id, slug: brandSlug };
}

function resolveFranchiseWefranchProfile(franchiseName) {
  const name = String(franchiseName || "").trim();
  if (!name) return null;

  const aliased = FRANCHISE_WEFRANCH_ALIASES[name] || name;
  return FRANCHISE_WEFRANCH_PROFILES[aliased] || FRANCHISE_WEFRANCH_PROFILES[name] || null;
}

function getFranchiseWefranchUrl(franchiseName) {
  const profile = resolveFranchiseWefranchProfile(franchiseName);
  if (!profile) return "";
  return `${WEFRANCH_FRANCHISE_BASE}/${profile.publicId}/${profile.slug}`;
}
